class Solution {
public:
    int cherryPickup(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        vector<vector<int>> dp(n, vector<int>(n, -1));
        dp[0][n - 1] = grid[0][0] + grid[0][n - 1];

        int dc[3] = {-1, 0, 1};

        for (int i = 0; i < m - 1; i++) {
            vector<vector<int>> ndp(n, vector<int>(n, -1));
            for (int j1 = 0; j1 < n; j1++) {
                for (int j2 = 0; j2 < n; j2++) {
                    if (dp[j1][j2] < 0) continue;
                    for (int d1 = 0; d1 < 3; d1++) {
                        int nj1 = j1 + dc[d1];
                        if (nj1 < 0 || nj1 >= n) continue;
                        for (int d2 = 0; d2 < 3; d2++) {
                            int nj2 = j2 + dc[d2];
                            if (nj2 < 0 || nj2 >= n) continue;
                            int gain = grid[i + 1][nj1] + (nj1 != nj2 ? grid[i + 1][nj2] : 0);
                            ndp[nj1][nj2] = max(ndp[nj1][nj2], dp[j1][j2] + gain);
                        }
                    }
                }
            }
            dp = move(ndp);
        }

        int ans = 0;
        for (int j1 = 0; j1 < n; j1++)
            for (int j2 = 0; j2 < n; j2++)
                ans = max(ans, dp[j1][j2]);
        return ans;
    }
};
